const app=document.querySelector('#app');
const icons={home:'M3 10 12 3l9 7v10H3ZM9 20v-7h6v7',box:'m3 7 9-4 9 4-9 4ZM3 7v10l9 4 9-4V7M12 11v10',truck:'M2 6h12v12H2ZM14 10h4l4 5v3h-8M5 18a2 2 0 1 0 4 0m7 0a2 2 0 1 0 4 0',chart:'M4 20V4M4 20h17M8 16v-5m5 5V7m5 9V3',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6ZM8 12l3 3 5-6',tool:'m14 4 3 3 4-1a7 7 0 0 1-9 9l-7 7-3-3 7-7a7 7 0 0 1 5-8',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',filter:'M3 5h18M6 12h12M9 19h6',check:'m5 12 4 4L19 6',plus:'M12 4v16M4 12h16',pin:'M18 9c0 5-6 11-6 11S6 14 6 9a6 6 0 1 1 12 0ZM14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 21h4',wallet:'M3 6h17v14H3ZM3 6V3h14v3M15 11h6v5h-6Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v6l4 2',play:'m8 4 12 8-12 8Z',close:'m5 5 14 14M5 19 19 5',phone:'M5 3h4l2 5-3 2 6 6 2-3 5 2v4c-8 4-20-8-16-16',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let playbackSpeed=1;let screen=new URLSearchParams(location.search).get('screen')||'home',tab='全部',paid=false,renewed=false,maintenanceSaved=false,playing=false,timer;
const status=()=>`<div class="statusbar"><span>9:41</span><span class="status-icons"><span class="signal"><i></i><i></i><i></i><i></i></span><span>◔</span><span class="battery"></span></span></div>`;
const button=(label,to,cls='primary-button')=>`<button class="${cls}" data-screen="${to}">${label}</button>`;
const nav=()=>`<nav class="bottomnav" aria-label="主要导航">${[['home','home','工作台'],['orders','box','运单'],['insurance','truck','车务'],['analytics','chart','统计']].map(([s,i,t])=>`<button data-screen="${s}" class="${screen===s?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;
const bar=(title,back='home',extra='')=>`<header class="appbar"><button data-screen="${back}" aria-label="返回">${icon('back')}</button><h1>${title}</h1>${extra||'<span class="spacer"></span>'}</header>`;
const route=()=>`<div class="route-row"><i class="route-dot"></i><div><b>西安 · 高新区</b><small>西安能源物流园</small></div></div><div class="route-row end-row"><i class="route-dot end"></i><div><b>太原 · 小店区</b><small>晋南物资中转中心</small></div></div>`;
const shipment=(n=28,state='运输中')=>`<article class="shipment"><div class="shipment-top"><span class="code">CY2026103100${n}</span><span class="pill ${state==='待装货'?'amber':''}">${state}</span></div>${route()}<div class="shipment-foot"><span class="driver-chip"><span class="driver-dot">陈</span>陕A·6M280</span><button class="text-button" data-screen="order-detail">查看详情 ${icon('arrow')}</button></div></article>`;
const tabs=(items)=>`<div class="tabs">${items.map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div>`;
const info=(a,b)=>`<div class="info-line"><span>${a}</span><b>${b}</b></div>`;
function home(){return `<header class="top-home"><div><div class="wordmark"><span class="mark">${icon('truck')}</span>运见<span style="font-size:9px;letter-spacing:2px;margin-left:2px">YUNJIAN</span></div><div class="greeting">早上好，朱经理 · 今天也一路顺畅</div></div><button class="user-avatar" data-screen="notifications" aria-label="待办消息">${icon('bell')}</button></header><main class="home-main"><section class="hero-balance"><div class="micro-row"><span>今日运输总量</span><span class="live">运营中</span></div><div class="balance-main"><strong>1,286.5</strong><span>吨</span></div><div class="hero-stat-grid"><div><small>运输中运单</small><b>18<em>单</em></b></div><div><small>出勤车辆</small><b>42<em>辆</em></b></div><div><small>运输完成率</small><b>96.8<em>%</em></b></div></div></section><div class="section-label"><h2>需要你关注</h2><span style="font-size:10px;color:#8992a5">让每件事都有着落</span></div><div class="tasks"><button class="task" data-screen="settlement"><span class="task-symbol">${icon('wallet')}</span><span><small>待核对账单</small><b>${paid?5:6}<span>笔</span></b></span></button><button class="task" data-screen="insurance"><span class="task-symbol amber">${icon('shield')}</span><span><small>保险即将到期</small><b>${renewed?2:3}<span>辆</span></b></span></button></div><div class="quick-links">${[['orders','box','全部运单'],['tracking','pin','车辆追踪'],['insurance','shield','保险管理'],['maintenance','tool','车辆保养']].map(([s,i,t])=>`<button data-screen="${s}"><span class="quick-icon">${icon(i)}</span>${t}</button>`).join('')}</div><div class="section-label"><h2>在途运单 <span style="font-size:11px;color:#8992a5;font-weight:400">/ 18</span></h2><button data-screen="orders">查看全部 ${icon('arrow')}</button></div>${shipment()}<p class="home-bottom-hint">已同步最新运输动态 · 09:40</p></main>${nav()}`}
function orders(){return `${bar('运输运单')}<main class="page-main"><div class="search-row"><label class="searchbox">${icon('search')}<input id="order-search" placeholder="搜索运单号、车牌或目的地" aria-label="搜索运单"></label><button class="filter-button" data-action="filter" aria-label="筛选运单">${icon('filter')}</button></div>${tabs(['全部','运输中','待装货','已完成'])}<div class="result-label">${tab==='全部'?'全部运单 · 18 单':tab+' · 示例运单'}</div><div id="order-results">${shipment(28,tab==='全部'?'运输中':tab)}${tab==='全部'?shipment(29,'待装货'):''}</div></main>${nav()}`}
function detail(){return `${bar('运单详情','orders')}<main class="page-main"><section class="detail-status"><div class="status-name">正在运输中 ${icon('truck')}</div><p>预计今天 16:30 到达 · 还有 168 km</p><div class="steps"><span class="done">已接单</span><span class="done">已装货</span><span class="done">运输中</span><span>已签收</span></div></section><section class="panel">${route()}<div class="driver-contact"><span class="driver-chip"><span class="driver-dot">陈</span><b>陈师傅</b> · 陕A·6M280</span><button data-action="contact" aria-label="联系司机">${icon('phone')}</button></div></section><section class="panel"><h2>货物与运输信息</h2>${info('运单编号','CY202610310028')}${info('货物名称','煤炭')}${info('装载重量','32.5 吨')}${info('装货时间','10月31日 08:20')}${info('运输里程','640 km')}</section><section class="panel"><h2>费用概览</h2>${info('基础运费','¥6,800.00')}${info('费用状态','待运输完成后对账')}</section></main><div class="fixed-action">${button('联系司机','', 'secondary-button').replace('data-screen=""','data-action="contact"')}${button('查看车辆位置','tracking')}</div>`}
function map(trajectory=false){return `<div class="map-screen">${bar(trajectory?'历史轨迹':'车辆追踪',trajectory?'tracking':'order-detail')}<div class="map-stage"><svg class="map-svg" viewBox="0 0 390 844" preserveAspectRatio="xMidYMid slice"><rect width="390" height="844" fill="#eef1f8"/><path d="M-50 320Q180 160 180 390T450 650" stroke="#d1e4f6" stroke-width="36" fill="none"/><g fill="#dfe6f2"><rect x="25" y="210" width="60" height="80" rx="9"/><rect x="240" y="130" width="110" height="65" rx="12"/><rect x="270" y="380" width="80" height="110" rx="9"/><rect x="25" y="450" width="90" height="80" rx="10"/></g><g stroke="white" stroke-width="12" fill="none"><path d="M-20 190 420 510M20 550 370 60M-20 400 410 220M110 0 300 650"/></g><g fill="#a0abc3" font-size="10"><text x="32" y="195">晋中市</text><text x="270" y="270">太原南站</text><text x="51" y="450">G5 京昆高速</text><text x="265" y="390">小店区</text></g><path d="M76 500 125 430 155 360 230 300 280 205" fill="none" stroke="white" stroke-width="10" stroke-linecap="round"/><path d="M76 500 125 430 155 360 230 300 280 205" fill="none" stroke="#5a79e4" stroke-width="5" stroke-linecap="round"/><circle cx="280" cy="205" r="8" fill="#ffcf86" stroke="#4164ed" stroke-width="3"/><g id="moving-marker" transform="translate(155 360)"><circle r="24" fill="#4164ed20"/><circle r="14" fill="#4164ed" stroke="white" stroke-width="3"/><path d="m-5 3 5-9 5 9-5-2Z" fill="#ffcf86"/></g></svg></div><div class="map-overlay-title"><div class="map-statuses"><span class="pill">${trajectory?'已记录 640 km':'车辆在线 · 09:40 更新'}</span></div></div><div class="map-controls"><button data-action="locate" aria-label="重新定位">${icon('pin')}</button></div><section class="map-bottom"><div class="vehicle-id-row"><div><h2>陕A·6M280</h2><p>陈师傅 · 运输中</p></div><div class="speed-block"><strong>68</strong><small>km/h</small></div></div>${trajectory?`<div class="trajectory-player"><div class="trajectory-player-top"><button class="play-trajectory" data-action="play" aria-label="播放轨迹">${icon('play')}</button><span id="play-time">08:20</span><button data-action="speed" id="speed">1×</button></div><input type="range" id="trajectory-range" aria-label="轨迹回放进度" min="0" max="100" value="35"><div class="traj-metrics"><span>行驶时长<b>7h 20m</b></span><span>停车次数<b>2 次</b></span><span>平均时速<b>68 km/h</b></span></div></div>`:`<div class="map-location">${icon('pin')}山西省晋中市 · 京昆高速太原方向</div><div class="map-buttons">${button('联系司机','','secondary-button').replace('data-screen=""','data-action="contact"')}${button('查看历史轨迹','trajectory')}</div>`}</section></div>`}
function settlement(){return `${bar('运费对账')}<main class="page-main"><section class="wallet-card"><span class="wallet-label">待核对运费 / 元</span><div class="wallet-value">${paid?'27,360.00':'34,200.00'}</div><div class="wallet-meta">${paid?5:6} 笔账单等待核对 · 截至今天 09:40</div></section>${tabs(['全部','待核对','已确认'])}<div class="result-label">${paid?'最新账单已确认':'按运输完成时间排序'}</div><article class="finance-card"><header><h3>西安 → 太原</h3><span class="pill ${paid?'':'amber'}">${paid?'已确认':'待核对'}</span></header><p class="text-note">CY202610310028 · 陕A·6M280</p><div class="finance-amount">¥6,840.00</div>${info('完成日期','2026.10.30')}<div class="action-row">${button('查看账单','reconcile','small-btn primary')}</div></article></main>${nav()}`}
function reconcile(){return `${bar('核对运费','settlement')}<main class="page-main"><section class="reconcile-total"><span class="amount-label">本次应结算金额 / 元</span><strong><span class="currency-symbol">¥</span>6,840<span class="amount-decimal">.00</span></strong><div class="bill-route"><span>西安</span><i>→</i><span>太原</span></div><small class="bill-number">运单编号 CY202610310028</small></section><section class="panel"><h2>费用明细</h2><div class="expense"><span>基础运费</span><b>¥6,800.00</b></div><div class="expense"><span>装卸补贴</span><b>+ ¥120.00</b></div><div class="expense"><span>货损扣款</span><b>− ¥80.00</b></div><div class="expense total"><span>应结算金额</span><b>¥6,840.00</b></div></section><section class="panel"><h2>运输凭证</h2><div class="receipt-strip"><div class="receipt">${icon('box')}<small>电子签收单</small></div><div class="receipt">${icon('check')}<small>重量确认单</small></div></div><p class="text-note">签收时间 2026.10.30 16:12 · 实收 32.5 吨</p></section><label class="check-row"><input id="agree" type="checkbox" ${paid?'checked':''}><span>我已核对运输信息、费用及签收凭证</span></label><p class="financial-safe">确认仅记录核对状态，不会发起付款</p></main><div class="fixed-action"><button class="primary-button" id="confirm-bill" data-action="confirm-bill" ${paid?'':'disabled'}>${paid?'查看确认结果':'确认账单'}</button></div>`}
function analytics(){return `${bar('运营统计')}<main class="page-main"><div class="period-switch">${['本周','本月','本年'].map((t,i)=>`<button data-period="${t}" class="${i===1?'active':''}">${t}</button>`).join('')}</div><div class="analytics-heading"><h2 id="period-title">2026年10月</h2><span class="pill">运营概览</span></div><div class="analytics-grid"><div class="analytics-tile"><small>运输总量 / 吨</small><strong id="stat-amount">32,680</strong><span>较上一周期 +12.8%</span></div><div class="analytics-tile"><small>完成运单 / 单</small><strong id="stat-count">486</strong><span>完成率 96.8%</span></div></div><section class="chart-panel"><div class="chart-title"><h2>运输量趋势</h2><span>单位：千吨</span></div><div class="bar-chart">${[42,65,53,82,68,95,79].map((h,i)=>`<div class="bar ${i===5?'focus':''}" style="height:${h}%"><small>${i*4+1}日</small></div>`).join('')}</div><p class="text-note">高峰运力集中在下旬，调度节奏更清晰</p></section><section class="panel"><h2>车队运输排行</h2>${['先锋车队','远行车队','致远车队'].map((t,i)=>`<div class="ranking-line"><span class="rank">0${i+1}</span><div class="rank-bar"><span>${t} <b style="float:right">${9800-i*1600} 吨</b></span><div class="rank-track"><i style="width:${92-i*17}%"></i></div></div></div>`).join('')}</section><p class="text-note">概念演示数据，仅用于展示统计交互。</p></main>${nav()}`}
function insurance(){return `${bar('保险管理','home',`<button data-screen="renew" aria-label="新增保险">${icon('plus')}</button>`)}<main class="page-main"><div class="risk-summary"><button data-tab="全部"><b>42</b><small>投保车辆</small></button><button class="risk-amber" data-tab="即将到期"><b>${renewed?2:3}</b><small>即将到期</small></button><button class="risk-red" data-tab="已逾期"><b>1</b><small>已逾期</small></button></div>${tabs(['全部','即将到期','已逾期'])}<div class="result-label">${tab==='已逾期'?'请优先处理逾期车辆':'优先展示需要处理的车辆'}</div><article class="vehicle-card"><header class="vehicle-card-header"><span class="task-symbol amber">${icon('shield')}</span><div><h3>陕A·6M280</h3><small>陈师傅 · 先锋车队</small></div><span class="pill ${renewed?'':tab==='已逾期'?'red':'amber'}">${renewed?'保障中':tab==='已逾期'?'已逾期':'剩余 7 天'}</span></header><div class="two-col"><div><small>保险类型</small><b>车辆商业险</b></div><div><small>保险公司</small><b>平安财险</b></div></div><p class="expires">保障至 ${renewed?'2027.11.07':'2026.11.07'} · 建议提前续保</p><div class="action-row">${button(renewed?'查看续保记录':'立即续保','renew','small-btn primary')}</div></article><article class="vehicle-card"><header class="vehicle-card-header"><span class="task-symbol">${icon('truck')}</span><div><h3>陕A·8K516</h3><small>张师傅 · 致远车队</small></div><span class="pill">保障中</span></header><p class="text-note">车辆交强险 · 保障至 2027.04.16</p><div class="action-row">${button('查看并续保','renew','small-btn')}</div></article><div class="section-label"><h2>更多车务</h2><button data-screen="maintenance">车辆保养 ${icon('arrow')}</button></div></main>${nav()}`}
function renew(){return `${bar('车辆续保','insurance')}<form id="renew-form" class="form-main" novalidate><div class="form-vehicle">${icon('truck')}<div><b>陕A·6M280</b><p>车辆商业险 · 原保障至 2026.11.07</p></div></div><section class="form-section"><h2>新的保障信息</h2><div class="form-field"><label for="company">保险公司 <em>*</em></label><select id="company" name="company"><option value="平安财险">平安财险</option><option>人保财险</option><option>太平洋财险</option></select></div><div class="form-row"><div class="form-field"><label for="start">生效日期 <em>*</em></label><input id="start" name="start" type="date" value="2026-11-08" required></div><div class="form-field"><label for="end">到期日期 <em>*</em></label><input id="end" name="end" type="date" value="2027-11-07" required></div></div><div class="form-field"><label for="premium">保费金额 / 元 <em>*</em></label><input id="premium" name="premium" type="number" min="0.01" step="0.01" placeholder="请输入本次保费" required></div></section><section class="form-section"><h2>上传保单 <small>选填</small></h2><label class="file-upload" id="upload-label">${icon('upload')}<span>点击添加保单照片</span><small>仅本地预览，不会上传</small><input id="policy-file" type="file" accept="image/*" aria-label="选择保单照片"></label></section><p class="submitting-note">提交前将再次确认保障日期与费用。</p><div class="fixed-action"><button class="primary-button" type="submit">下一步 · 确认信息</button></div></form>`}
function maintenance(){return `${bar('车辆保养','home',`<button data-screen="maintenance-add" aria-label="新增保养">${icon('plus')}</button>`)}<main class="page-main"><section class="wallet-card"><span class="wallet-label">让每一程，都有可靠的准备</span><div class="wallet-value" style="font-size:27px">车辆养护计划</div><div class="wallet-meta">3 辆车即将到达保养里程</div></section>${tabs(['全部','待保养','已完成'])}<div class="result-label">${maintenanceSaved?'新增保养记录已保存':'按预计保养时间排序'}</div><article class="vehicle-card"><header class="vehicle-card-header"><span class="task-symbol">${icon('tool')}</span><div><h3>陕A·6M280</h3><small>陈师傅 · 先锋车队</small></div><span class="pill ${maintenanceSaved?'':'amber'}">${maintenanceSaved?'已保养':'待保养'}</span></header><div class="two-col"><div><small>当前里程</small><b>86,420 km</b></div><div><small>保养项目</small><b>机油 · 滤芯更换</b></div></div><p class="expires">建议 2026.11.05 前完成常规保养</p><div class="action-row">${button('记录本次保养','maintenance-add','small-btn primary')}</div></article></main>${nav()}`}
function maintenanceForm(){return `${bar('新增保养记录','maintenance')}<form id="maintenance-form" class="form-main" novalidate><section class="form-section"><h2>车辆与时间</h2><div class="form-field"><label for="vehicle">选择车辆</label><select id="vehicle" name="vehicle"><option>陕A·6M280</option><option>陕A·8K516</option></select></div><div class="form-row"><div class="form-field"><label for="date">保养日期</label><input id="date" name="date" type="date" value="2026-10-31" required></div><div class="form-field"><label for="mileage">当前里程 / km</label><input id="mileage" name="mileage" type="number" value="86420" min="1" required></div></div></section><section class="form-section"><h2>保养项目</h2><div id="items">${item(1)}</div><button type="button" class="add-item" data-action="add-item">${icon('plus')} 添加保养项目</button></section><div class="form-field"><label for="note">备注</label><textarea id="note" placeholder="记录本次保养情况（选填）"></textarea></div><div class="fixed-action"><div class="form-total"><small>合计费用</small><strong id="maintenance-total">¥0.00</strong></div><button class="primary-button" type="submit">保存记录</button></div></form>`}
function item(n){return `<div class="item-editor"><header class="item-editor-header"><b>保养项目 ${n}</b><button type="button" data-action="remove-item" aria-label="删除此项目">${icon('close')}</button></header><div class="form-field"><label>项目名称<input name="item-name" placeholder="例如：更换机油" required></label></div><div class="form-field"><label>费用 / 元<input name="item-cost" type="number" min="0.01" step="0.01" placeholder="0.00" required></label></div></div>`}
function notifications(){return `${bar('待办与消息')}<main class="page-main notifications-list">${[['settlement','运费账单待核对','西安 → 太原的运输已完成，点击核对费用。'],['insurance','车辆保险临期提醒','陕A·6M280 的商业险将在 7 天后到期。'],['tracking','运单最新动态','陈师傅已驶入晋中市，预计 16:30 到达。']].map(([s,t,p])=>`<button class="notification" data-screen="${s}"><strong>${t}</strong><p>${p}</p><small>今天 09:40 ${icon('arrow')}</small></button>`).join('')}</main>`}
const views={home,orders,'order-detail':detail,tracking:()=>map(false),trajectory:()=>map(true),settlement,reconcile,analytics,insurance,renew,maintenance,'maintenance-add':maintenanceForm,notifications};
function go(s){if(!views[s])return;clearInterval(timer);playing=false;screen=s;tab='全部';render();window.scrollTo(0,0);history.replaceState({},'',`?screen=${s}`)}
function render(){app.innerHTML=`<div class="app-shell">${status()}${views[screen]?.()||home()}</div>`;document.title=`运见 · ${screen}`;if(screen==='insurance'&&tab!=='全部'){document.querySelectorAll('.vehicle-card')[1]?.remove();if(tab==='已逾期'){const p=document.querySelector('.expires');if(p)p.textContent='保障已于 2026.10.20 到期 · 请尽快续保';}}if(screen==='settlement'&&((tab==='已确认'&&!paid)||(tab==='待核对'&&paid))){document.querySelector('.finance-card').outerHTML='<div class="empty-state">'+icon('check')+'<h3>暂无'+tab+'账单</h3><p>切换其他状态查看账单</p></div>';}} 
function sheet(title,body,actions=''){document.querySelector('.sheet-backdrop')?.remove();app.insertAdjacentHTML('beforeend',`<div class="sheet-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><button class="sheet-close" data-action="close" aria-label="关闭">${icon('close')}</button><h2>${title}</h2>${body}<div class="sheet-actions">${actions}</div></section></div>`);document.querySelector('.sheet button')?.focus()}
function toast(t){document.querySelector('.toast')?.remove();app.insertAdjacentHTML('beforeend',`<div class="toast" role="status">${t}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),2400)}
function success(title,desc,to){document.querySelector('.sheet-backdrop')?.remove();app.innerHTML=`<div class="app-shell">${status()}${bar('处理结果',to)}<main class="success-view"><div class="success-badge">${icon('check')}</div><h1>${title}</h1><p>${desc}</p><div class="success-summary">${info('车辆','陕A·6M280')}${info('处理时间','2026.10.31 09:41')}${info('记录状态','已更新')}</div>${button('完成 · 返回列表',to)}</main></div>`}
app.addEventListener('click',e=>{const b=e.target.closest('button,[data-screen]');if(!b)return;if(b.dataset.screen){go(b.dataset.screen);return}if(b.dataset.tab){tab=b.dataset.tab;render();return}if(b.dataset.period){document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('active',x===b));const p=b.dataset.period;document.querySelector('#period-title').textContent=p==='本周'?'10月26日 — 11月1日':p==='本年'?'2026年':'2026年10月';document.querySelector('#stat-amount').textContent=p==='本周'?'8,246':p==='本年'?'286,540':'32,680';document.querySelector('#stat-count').textContent=p==='本周'?'128':p==='本年'?'4,082':'486';document.querySelectorAll('.bar-chart .bar').forEach((x,i)=>x.style.height=(35+(i*17+(p==='本周'?20:p==='本年'?8:0))%62)+'%');return}switch(b.dataset.action){case'close':document.querySelector('.sheet-backdrop')?.remove();break;case'contact':sheet('联系司机',`<div class="confirm-box"><h3>陈师傅 · 陕A·6M280</h3><p>联系电话：138 **** 6028</p><p class="text-note">作品集交互演示，电话号码已脱敏。</p></div>`,`<button class="primary-button" data-action="close">知道了</button>`);break;case'filter':sheet('筛选运单',`<h3>运输状态</h3><div class="choice-grid">${['全部','运输中','待装货','已完成'].map(t=>`<button class="choice ${t===tab?'selected':''}" data-choice="${t}">${t}</button>`).join('')}</div><h3>时间范围</h3><p>2026.10.01 — 2026.10.31</p>`,`<button class="secondary-button" data-action="reset-filter">重置</button><button class="primary-button" data-action="apply-filter">应用筛选</button>`);break;case'reset-filter':tab='全部';document.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x.dataset.choice==='全部'));break;case'apply-filter':render();break;case'confirm-bill':sheet('确认这笔账单？',`<div class="confirm-box"><h3>¥6,840.00</h3><p>基础运费 ¥6,800 + 补贴 ¥120 − 扣款 ¥80</p><p class="text-note">确认后记录为已核对。本演示不会发起付款。</p></div>`,`<button class="secondary-button" data-action="close">返回检查</button><button class="primary-button" data-action="bill-done">确认无误</button>`);break;case'bill-done':paid=true;success('账单已确认','本次运费 ¥6,840.00 已核对完成。','settlement');break;case'renew-done':renewed=true;success('续保记录已保存','新的保障信息已同步至车辆档案。','insurance');break;case'maintenance-done':maintenanceSaved=true;success('保养记录已保存','费用与保养项目已记录，方便后续追溯。','maintenance');break;case'locate':document.querySelector('#moving-marker').setAttribute('transform','translate(155 360)');toast('已回到当前车辆位置');break;case'play':playing=!playing;b.setAttribute('aria-label',playing?'暂停轨迹':'播放轨迹');b.innerHTML=playing?'Ⅱ':icon('play');clearInterval(timer);if(playing)timer=setInterval(()=>{const r=document.querySelector('#trajectory-range');if(!r)return; r.value=(+r.value+playbackSpeed)%101;r.dispatchEvent(new Event('input',{bubbles:true}));},150);break;case'speed':playbackSpeed=playbackSpeed===1?2:playbackSpeed===2?4:1;b.textContent=playbackSpeed+'×';break;case'add-item':document.querySelector('#items').insertAdjacentHTML('beforeend',item(document.querySelectorAll('.item-editor').length+1));break;case'remove-item':if(document.querySelectorAll('.item-editor').length>1){b.closest('.item-editor').remove();total()}else toast('请至少保留一个保养项目');break;}if(b.dataset.choice){tab=b.dataset.choice;document.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b))}});
function total(){const n=[...document.querySelectorAll('[name="item-cost"]')].reduce((a,x)=>a+(+x.value||0),0);document.querySelector('#maintenance-total').textContent='¥'+n.toFixed(2)}
app.addEventListener('input',e=>{if(e.target.id==='agree')document.querySelector('#confirm-bill').disabled=!e.target.checked;if(e.target.name==='item-cost')total();if(e.target.id==='order-search'){const q=e.target.value.trim();document.querySelector('#order-results').innerHTML=!q||['CY202610310028','陕A·6M280','西安','太原'].some(x=>x.toLowerCase().includes(q.toLowerCase()))?shipment():`<div class="empty-state">${icon('search')}<h3>没有找到相关运单</h3><p>试试车牌、运单号或目的地</p></div>`}if(e.target.id==='trajectory-range'){const v=+e.target.value;document.querySelector('#moving-marker').setAttribute('transform',`translate(${76+204*v/100} ${500-295*v/100})`);document.querySelector('#play-time').textContent=`${String(8+Math.floor(v*7/100)).padStart(2,'0')}:${String(Math.floor(v*60/100)%60).padStart(2,'0')}`}});
app.addEventListener('change',e=>{if(e.target.id==='policy-file'&&e.target.files[0]){const r=new FileReader;r.onload=()=>{const l=document.querySelector('#upload-label');l.querySelector('img')?.remove();l.insertAdjacentHTML('afterbegin',`<img alt="所选保单本地预览" src="${r.result}" style="width:60px;height:60px;object-fit:cover;border-radius:8px">`);};r.readAsDataURL(e.target.files[0])}});
app.addEventListener('submit',e=>{e.preventDefault();const f=e.target;f.querySelectorAll('.field-error').forEach(x=>x.remove());f.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));let invalid=[...f.querySelectorAll('[required]')].filter(x=>!x.checkValidity());if(f.id==='renew-form'&&f.end.value<=f.start.value)invalid.push(f.end);if(invalid.length){invalid.forEach(x=>{x.setAttribute('aria-invalid','true');x.insertAdjacentHTML('afterend','<small class="field-error" style="color:#bc5c4a">请填写有效信息，到期日须晚于生效日</small>')});invalid[0].focus();return}if(f.id==='renew-form')sheet('确认续保信息',`<div class="confirm-box">${info('车辆','陕A·6M280')}${info('保险公司',esc(f.company.value))}${info('保障日期',esc(f.start.value)+' 至 '+esc(f.end.value))}${info('保费','¥'+(+f.premium.value).toFixed(2))}</div>`,`<button class="secondary-button" data-action="close">返回修改</button><button class="primary-button" data-action="renew-done">确认保存</button>`);else sheet('确认保养记录',`<div class="confirm-box">${info('车辆',esc(f.vehicle.value))}${info('保养日期',esc(f.date.value))}${info('项目数量',f.querySelectorAll('.item-editor').length+' 项')}${info('费用合计',document.querySelector('#maintenance-total').textContent)}</div>`,`<button class="secondary-button" data-action="close">返回修改</button><button class="primary-button" data-action="maintenance-done">确认保存</button>`)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.sheet-backdrop')?.remove()});window.CarrierDemo={go,get screen(){return screen}};render();

